3. Save the downloaded content to a file in the DOWNLOAD_DIR.
4. Extract the zip file into the ZIP_DIR using zipfile.
5. Collect the list of filenames from the extracted directory.
6. Return a tuple with a success status message and the list of filenames.
7. Handle network errors by returning a tuple with an error status message and an empty list.
8. Handle file or extraction errors by returning a tuple with an error status message and an empty list.

### code
```python
import requests
from pathlib import Path
import zipfile

DOWNLOAD_DIR = Path("downloads")
ZIP_DIR = Path("unzipped_files")

def task_func(url, filename):
    if not url or not filename:
        return ("Error: URL and filename must be provided.", [])
    try:
        response = requests.get(url, verify=False)
        response.raise_for_status()
    except requests.RequestException as e:
        return (f"Error: Network issue - {e}", [])
    try:
        DOWNLOAD_DIR.mkdir(exist_ok=True)
        zip_path = DOWNLOAD_DIR / filename
        with open(zip_path, 'wb') as f:
            f.write(response.content)
    except (IOError, OSError) as e:
        return (f"Error: File save issue - {e}", [])
    try:
        ZIP_DIR.mkdir(exist_ok=True)
        with zipfile.ZipFile(zip_path, 'r') as zip_ref:
            zip_ref.extractall(ZIP_DIR)
        filenames = [f.name for f in ZIP_DIR.iterdir() if f.is_file()]
        return ("Success", filenames)
    except (zipfile.BadZipFile, IOError, OSError) as e:
        return (f"Error: Extraction issue - {e}", [])
