        if not tables:
            return 0
        df = tables[0]
        if df.empty:
            return 0
        rows_count = len(df)
    except Exception as e:
        raise ValueError(f"Error parsing HTML table: {e}")
    try:
        conn = sqlite3.connect(database_name)
        cursor = conn.cursor()
        cursor.execute("DROP TABLE IF EXISTS my_table")
        df.to_sql("my_table", conn, index=False)
        conn.commit()
        conn.close()
    except sqlite3.DatabaseError as e:
        raise sqlite3.DatabaseError(f"Database error: {e}")
    return rows_count

